# Generate the full replacement flow JSON
python3 - << 'PYEOF'
import json

flow_path = "/work/output/artifacts/skill-flow-ixp-invoice-extraction-simulated/InvoiceAutomation/InvoiceAutomation/InvoiceAutomation.flow"

with open(flow_path) as f:
    flow = json.load(f)

with open('/tmp/ixp_full_def.json') as f:
    ixp_def = json.load(f)
with open('/tmp/end_def.json') as f:
    end_def = json.load(f)
with open('/tmp/terminate_def.json') as f:
    terminate_def = json.load(f)
with open('/tmp/def_script.json') as f:
    script_def_raw = json.load(f)

script_def = script_def_raw['Data']['Node'] if 'Data' in script_def_raw else script_def_raw

# Fix IXP modelName per impl authoring rule #1
ixp_model_blob = dict(ixp_def.get('inputDefaults', {}).get('model', {}))
if not ixp_model_blob.get('modelName'):
    ixp_model_blob['modelName'] = ixp_model_blob.get('modelDisplayName', 'InvoiceIXP')

ixp_flat = ixp_def.get('inputDefaults', {})
ixp_output_def = ixp_def.get('outputDefinition', {})
ixp_node_type = "uipath.ixp.invoiceixp-cef0d447-ixp.ff973488-5d89-8035-86ac-f980b4be6deb-c4359cde-55f0-4f0e-9322-c6cdce74ab4c"
ixp_type_version = ixp_def.get('version', '1.0.0')

# --- USER-OWNED NODES ---
extract_node = {
    "id": "extractInvoiceFields1",
    "type": ixp_node_type,
    "typeVersion": ixp_type_version,
    "display": {"label": "Extract Invoice Fields"},
    "inputs": {
        "model": ixp_model_blob,
        "modelName": ixp_flat.get('modelName', 'invoiceixp-cef0d447-ixp'),
        "description": "",
        "projectName": ixp_flat.get('projectName', 'invoiceixp-cef0d447-ixp'),
        "versionTag": "",
        "folderKey": ixp_flat.get('folderKey', 'c4359cde-55f0-4f0e-9322-c6cdce74ab4c'),
        "folderName": ixp_flat.get('folderName', 'Shared'),
        "fileRef": "=js:$vars.getFileFromSharepoint1.output",
        "pageRange": ""
    },
    "outputs": {
        "output": ixp_output_def.get('output', {}),
        "error": ixp_output_def.get('error', {})
    }
}

script_body = """const fields = ($vars.extractInvoiceFields1.output && $vars.extractInvoiceFields1.output.ExtractionResult && $vars.extractInvoiceFields1.output.ExtractionResult.ResultsDocument && $vars.extractInvoiceFields1.output.ExtractionResult.ResultsDocument.Fields) ? $vars.extractInvoiceFields1.output.ExtractionResult.ResultsDocument.Fields : [];
const get = (name) => { const f = fields.find(function(x){return x.FieldName === name;}); return f && f.Values && f.Values.length > 0 ? f.Values[0] : null; };
const lineItems = ($vars.extractInvoiceFields1.output && $vars.extractInvoiceFields1.output.ExtractionResult && $vars.extractInvoiceFields1.output.ExtractionResult.ResultsDocument && $vars.extractInvoiceFields1.output.ExtractionResult.ResultsDocument.Tables) ? $vars.extractInvoiceFields1.output.ExtractionResult.ResultsDocument.Tables : [];
return {
  invoiceNumber: get('InvoiceNumber') || get('invoiceNumber') || get('Invoice Number'),
  vendorName:    get('VendorName')    || get('vendorName')    || get('Vendor Name'),
  invoiceDate:   get('InvoiceDate')   || get('invoiceDate')   || get('Invoice Date'),
  totalAmount:   get('TotalAmount')   || get('totalAmount')   || get('Total Amount') || get('Total'),
  lineItems:     lineItems
};"""

map_node = {
    "id": "mapFieldsToSap1",
    "type": "core.action.script",
    "typeVersion": script_def.get('version', '1.0'),
    "display": {"label": "Map Fields to SAP Payload"},
    "inputs": {
        "language": "javascript",
        "script": script_body
    },
    "outputs": {
        "output": {
            "type": "object",
            "description": "SAP invoice payload",
            "source": "=output",
            "var": "output"
        },
        "error": {
            "type": "object",
            "description": "Error information",
            "source": "=Error",
            "var": "error"
        }
    }
}

done_node = {
    "id": "doneSuccess1",
    "type": "core.control.end",
    "typeVersion": end_def.get('version', '1.0'),
    "display": {"label": "Done"},
    "inputs": {},
    "outputs": {}
}

terminate_node = {
    "id": "fatalError1",
    "type": "core.logic.terminate",
    "typeVersion": terminate_def.get('version', '1.0'),
    "display": {"label": "Fatal Error"},
    "inputs": {
        "message": "=js:'Invoice automation failed. Check $vars for error details.'"
    }
}

# --- ADD USER-OWNED NODES TO nodes[] ---
flow['nodes'].extend([extract_node, map_node, done_node, terminate_node])

# --- ADD DEFINITIONS ---
defs_to_add = [ixp_def, script_def, end_def, terminate_def]
existing_types = {d.get('nodeType') for d in flow.get('definitions', [])}
for d in defs_to_add:
    nt = d.get('nodeType')
    if nt and nt not in existing_types:
        flow['definitions'].append(d)
        existing_types.add(nt)

# --- WIRE ALL EDGES ---
flow['edges'] = [
    # trigger → get file
